"""Generate docs/MODEL_CARD.md from the metrics files, so every number is sourced.   python3 scripts/make_model_card.py"""
import json, os

R = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
j = lambda f: json.load(open(os.path.join(R, "public", f)))
sim, real = j("metrics.json"), j("metrics_physionet.json")
aud = j("audit_physionet.json") if os.path.exists(os.path.join(R, "public", "audit_physionet.json")) else None
pct = lambda v, d=0: f"{100 * v:.{d}f}%"
ci = lambda c: f"{c[0]:.2f}–{c[1]:.2f}"
ra, rs = real["alerting"], sim["alerting"]
L = []
add = L.append
add("# AuraZ model card\n")
add("*Generated by `scripts/make_model_card.py` from `public/*.json`. Research prototype. **Not a medical device.***\n")
add("## Intended use\nRetrospective research on hourly ICU sepsis early warning, and a demonstration of scoring beside hospital data on IBM Z / LinuxONE. "
    "Not for clinical decision-making, diagnosis or triage. Any clinical use needs local recalibration, a prospective silent-mode study and regulatory review.\n")
add("## Models\n"
    "| Model | Data | Method | Use |\n|---|---|---|---|\n"
    "| Demo model | Simulated ICU cohort (5,000 / 1,500 / 3,000 stays) | Logistic regression, 16 features, exact explanations | Demonstrates the pipeline, conformal labels, alert budget and IBM Z serving |\n"
    f"| **AuraZ-R** | PhysioNet/CinC 2019 real ICU data ({real['cohorts']['train'] + real['cohorts']['calibration'] + real['cohorts']['test']:,} stays) | 300 gradient-boosted trees, {real['n_features']} features (all 34 clinical variables, measurement recency, trends, demographics) | Real-data performance claims |\n")
add("Both predict Sepsis-3 onset within the next 6 hours, scored hourly. Uncertainty uses class-conditional split conformal prediction (alpha 0.10); alert thresholds are set on a separate calibration split under a false-alarm budget.\n")
add("## Performance\n")
add(f"**Simulated cohort (method demonstration, {sim['cohorts']['test']:,} held-out stays, {sim['cohorts']['test_septic']} septic):** AUROC {sim['auroc']:.3f} ({ci(sim['auroc_ci95'])}); "
    f"{pct(rs['model']['sensitivity'])} of septic patients alerted vs {pct(rs['baseline_sirs_rule']['sensitivity'])} for SIRS at {rs['model']['false_alerts_per_100_patient_days']:.1f} vs {rs['baseline_sirs_rule']['false_alerts_per_100_patient_days']:.1f} false alerts/100 patient-days.\n")
add(f"**AuraZ-R on real data ({real['cohorts']['test']:,} held-out stays, {real['cohorts']['test_septic']} septic):** AUROC **{real['auroc']:.3f}** ({ci(real['auroc_ci95'])}); "
    f"{real['ablations']['without_icu_time']:.3f} without ICU-time features; {real['ablations']['without_icu_time_and_recency']:.3f} also without measurement recency; "
    f"first 16-feature model {real['baselines']['logistic_16_features']:.3f}. Conformal coverage {pct(real['conformal']['coverage_septic_hours'], 1)} (septic) / {pct(real['conformal']['coverage_nonseptic_hours'], 1)} (non-septic), target 90%.\n")
m = ra.get("model_at_sirs_false_alert_rate")
add("| Real-data alerting | Septic patients alerted | False alerts / 100 patient-days |\n|---|---|---|\n"
    f"| AuraZ-R, low-burden setting | {pct(ra['model']['sensitivity'])} | {ra['model']['false_alerts_per_100_patient_days']:.1f} |\n"
    + (f"| AuraZ-R at SIRS's alarm rate | {pct(m['sensitivity'])} | {m['false_alerts_per_100_patient_days']:.1f} |\n" if m else "")
    + f"| SIRS ≥ 2 | {pct(ra['baseline_sirs_rule']['sensitivity'])} | {ra['baseline_sirs_rule']['false_alerts_per_100_patient_days']:.1f} |\n")
if aud:
    add("## External validation (train on one hospital, test on the other)\n")
    add("| Train → test | Test septic stays | AUROC (95% CI) | Coverage septic · non-septic |\n|---|---|---|---|")
    for k, x in aud["cross_hospital"].items():
        c = x["conformal"]; cs = "—" if c["coverage_septic_hours"] is None else pct(c["coverage_septic_hours"])
        add(f"| {k.replace('train_', '').replace('_test_', ' → ')} | {x['test_septic']} | {x['auroc']:.3f} ({ci(x['auroc_ci95'])}) | {cs} · {pct(c['coverage_nonseptic_hours'])} |")
    p = aud["pooled_split"]
    add(f"\nPooled random split for comparison: AUROC {p['auroc']:.3f} ({ci(p['auroc_ci95'])}). **Cross-hospital performance is lower and uncertainty coverage does not fully transfer: recalibrate per hospital.**\n")
    add("## Subgroup audit (same operating point for every group)\n")
    add("| Subgroup | Septic stays | AUROC | Alert rate | Septic hours alerted |\n|---|---|---|---|---|")
    for k, g in aud["subgroups"].items():
        if k == "operating_point": continue
        add(f"| {k} | {g.get('septic_stays', '—')} | {g['auroc']:.3f} | {g['alert_rate_pct']:.1f}% | {g['sensitivity_hour_pct']:.0f}% |" if "auroc" in g else f"| {k} | — | {g.get('note', '—')} | | |")
    add(f"\n{aud['subgroups']['operating_point']}. Subgroups have few septic stays; differences are a screening signal, not proof of bias. Race/ethnicity is not in the dataset and was not audited.\n")
add("## Limitations\n"
    "- Headline demo numbers are simulated. Real-data results come from retrospective PhysioNet 2019 data from two US hospitals.\n"
    "- Measurement-recency features partly encode clinician behaviour; ICU length of stay is the top feature (AUROC without it is reported above).\n"
    "- No prospective validation, no regulatory clearance, no race/ethnicity audit.\n"
    "- Inference on IBM z17 (LinuxONE Community Cloud) used the CPU; the Telum II NNPA accelerator was **not** used.\n")
add("## Reproduce\n```bash\npython3 ml/train.py                 # demo model + simulated metrics\npython3 ml/train_physionet_gbm.py   # AuraZ-R (needs data/physionet2019/)\npython3 ml/audit_physionet.py       # external validation + subgroups\nnpm test && python3 -m unittest ml/test_serve.py\n```\n")
open(os.path.join(R, "docs", "MODEL_CARD.md"), "w").write("\n".join(L))
print("wrote docs/MODEL_CARD.md")
